    /**
     * Returns the generated item type constant with the supplied identifier.
     *
     * @param id item identifier
     * @return matching generated item type constant, if present
     */
    public static Optional<ItemType> get(Identifier id) {
        Objects.requireNonNull(id, "id");
        return Optional.ofNullable(Lookup.VALUES.get(id));
    }

    private static final class Lookup {
        private static final Map<Identifier, ItemType> VALUES = create();

        private static Map<Identifier, ItemType> create() {
            Map<Identifier, ItemType> values = new LinkedHashMap<>();
            for (Field field : ItemTypes.class.getFields()) {
                if (field.getType() != ItemType.class) {
                    continue;
                }
                try {
                    ItemType type = (ItemType) field.get(null);
                    values.put(type.getId(), type);
                } catch (IllegalAccessException e) {
                    throw new IllegalStateException("Unable to read item type field " + field.getName(), e);
                }
            }
            return Map.copyOf(values);
        }
    }
